schema:
{
  "description": "Contratti di fornitura: verifica delle condizioni",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "DataDecorrenza": {
        "type": "date",
        "method": "extract",
        "description": "Data da cui decorre il contratto, nell'articolo sulla durata."
      },
      "DurataMesi": {
        "type": "number",
        "method": "extract",
        "description": "Durata in mesi indicata nell'articolo sulla durata."
      },
      "RinnovoTacito": {
        "type": "boolean",
        "method": "classify",
        "description": "Vero se il contratto si rinnova automaticamente alla scadenza."
      },
      "PreavvisoGiorni": {
        "type": "number",
        "method": "extract",
        "description": "Giorni di preavviso per la disdetta, nell'articolo sul recesso."
      },
      "PenaleSettimanalePercento": {
        "type": "number",
        "method": "extract",
        "description": "Percentuale di penale per settimana di ritardo."
      },
      "ForoCompetente": {
        "type": "string",
        "method": "extract",
        "description": "Città del foro competente per le controversie."
      }
    }
  }
}
